HELPERS = r'''import json, datetime, re
def _obj(name):
    v = vars.get(name)
    if isinstance(v, (dict, list)):
        return v
    if isinstance(v, str) and v.strip()[:1] in ('{', '['):
        try:
            return json.loads(v)
        except Exception:
            try:
                import ast
                return ast.literal_eval(v)
            except Exception:
                pass
    pre = name + '.'
    out = {}
    for k in list(vars.keys()):
        if isinstance(k, str) and k.startswith(pre):
            parts = k[len(pre):].split('.')
            cur = out
            for p in parts[:-1]:
                if not isinstance(cur.get(p), dict):
                    cur[p] = {}
                cur = cur[p]
            cur[parts[-1]] = vars[k]
    if out:
        def fix(o):
            if isinstance(o, dict):
                keys = list(o.keys())
                if keys and all(re.match(r'^[0-9]+$', x) for x in keys):
                    return [fix(o[x]) for x in sorted(keys, key=int)]
                return dict((a, fix(b)) for a, b in o.items())
            return o
        return fix(out)
    return None
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
def _w3(n):
    h = n // 100; t = (n % 100) // 10; o = n % 10
    s = []
    if h:
        if h > 1: s.append(ONES[h])
        s.append('yüz')
    if t: s.append(TENS[t])
    if o: s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    s = []
    for val, nm in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q = n // val
        if q:
            if nm == 'bin' and q == 1: s.append('bin')
            else: s.append(_w3(q) + ' ' + nm)
            n = n % val
    if n: s.append(_w3(n))
    return ' '.join(s)
CUR = {'TL': ('Türk Lirası', 'kuruş'), 'USD': ('Dolar', 'sent'), 'EUR': ('Euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'peni')}
def num(x):
    try: return float(x)
    except Exception: return 0.0
def money(x, c):
    x = round(abs(num(x)) + 1e-9, 2)
    i = int(x); k = int(round((x - i) * 100))
    nm, sub = CUR[c]
    s = words(i) + ' ' + nm
    if k: s += ' ' + words(k) + ' ' + sub
    return s
MONTHS = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
def pdate(s):
    try:
        s = str(s or '').strip()
        if re.match(r'^\d{2}\.\d{2}\.\d{4}$', s):
            return datetime.date(int(s[6:10]), int(s[3:5]), int(s[0:2]))
        if re.match(r'^\d{4}-\d{2}-\d{2}', s):
            return datetime.date.fromisoformat(s[:10])
    except Exception:
        pass
    return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month-1] + ' ' + str(d.year) if d else ''
DIG = ['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
def digits_words(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def today():
    try: return datetime.date.fromisoformat(str(vars.get('today_iso'))[:10])
    except Exception: return datetime.date.today()
def cards():
    c = _obj('cards_data')
    if isinstance(c, dict) and 'cards' in c: c = c['cards']
    if not isinstance(c, list): c = []
    return [x for x in c if isinstance(x, dict)]
def intro(card):
    l4 = digits_words(card.get('cardNumberLast4') or str(card.get('cardNumber', ''))[-4:])
    pn = str(card.get('productName') or '').strip()
    return 'Sonu ' + l4 + ' ile biten ' + (pn + ' kartınız' if pn else 'kartınız')
ORD = {1: 'birinci', 2: 'ikinci', 3: 'üçüncü', 4: 'dördüncü'}
'''

