    if not card.get('cardNumberLast4'): card = dict(card, cardNumberLast4=b.get('cardNumberLast4') or str(b.get('cardNumber',''))[-4:])
    td = today()
    sd = pdate(b.get('statementDate')); dd = pdate(b.get('lastPayDate'))
    nsd = pdate(b.get('nextStatementDate')); ndd = pdate(b.get('nextLastPayDate'))
    keys = [('TL', 'debtTL'), ('USD', 'debtUSD'), ('EUR', 'debtEUR'), ('GBP', 'debtGBP')]
    blocks = {}
    for c, k in keys:
        v = b.get(k)
        if isinstance(v, dict) and v:
            blocks[c] = v
