        vars['pdf_possible'] = 'yes'
    else:
        debt_cur = [c for c, k in keys if c in blocks and has_debt(blocks[c])]
        if str(b.get('statementPaymentStatus')) == 'NO_DEBT' or not debt_cur:
            s = ito + 'ın ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tl = blocks.get('TL', {})
            if num(tl.get('totalDebt')) > 0.004:
                s += ' Gelecek dönemler dahil toplam borcunuz ' + money(tl.get('totalDebt'), 'TL') + '.'
            if dd:
                s += ' Son ödeme tarihiniz ' + sdate(dd) + ' olacaktır.'
            parts.append(s)
