                rd = money(v.get('remainingDebt'), c); rm = money(v.get('remainingMinPayment'), c)
                if c == 'TL':
                    rmn = num(v.get('remainingMinPayment')); mnn = num(v.get('minPayment'))
                    if rmn > 0.004 and rmn >= mnn - 0.004:
                        s = 'Türk Lirası borcunuz ' + st + ', ödenmesi gereken minimum tutar ' + mn + '.'
