            d['ok'] = 'yes'
        else:
            code = ''
            if isinstance(d, dict) and isinstance(d.get('result'), dict):
                code = str(d['result'].get('code') or '')
            result['data'] = {'ok': 'no', 'code': code or 'ERROR', 'result': {'returnCode': code or 'ERROR'}, 'what_to_do_next': 'Servis hata verdi. Hiçbir işlem yapılmadı. Başarılı olduğunu asla söyleme.'}
except Exception:
