    pn = str(card.get('productName') or '').strip()
    return 'Sonu ' + l4 + ' ile biten ' + (pn + ' kartınız' if pn else 'kartınız')
ORD = {1: 'birinci', 2: 'ikinci', 3: 'üçüncü', 4: 'dördüncü'}
